export function UserIcon({ title, placement, imgStyle, outerStyle }) {
  return (
    <OverlayTrigger
      key="a"
      placement={placement || "left"}
      overlay={
        <Tooltip id="tooltip-disabled">
          {title || UI_TEXTS.HEADINGS.PROFILE}
        </Tooltip>
      }
    >
      <span style={{ ...outerStyle }}>
        <img
          loading="lazy"
          data-testid="user-icon"
          key="ab"
          alt=""
          style={{ height: "32px", width: "32px", ...imgStyle }}
          src={userProfileIcon}
        />{" "}
      </span>
    </OverlayTrigger>
  );
}

