export function DateTimeIconHtml({
  date,
  type = "created",
  title,
  breakLine = true,
}) {
  const calenderIcon = type === "updated" ? faCalendarPlus : faCalendarAlt;
  let tooltipText = null;
  if (title) {
    tooltipText = `${title} (UTC)`;
  } else {
    tooltipText =
      type === "updated" ? "Last Updated On (UTC)" : "Created On (UTC)";
  }
  const formattedDate = getDateFormatByRegion(date);
  console.log("formattedDate", formattedDate);
  const [datePart, timePart] = formattedDate.split(" | ");
  return (
    <OverlayTrigger
      placement="top"
      overlay={
        <Tooltip id="tooltip-disabled">
          {tooltipText} <br />
          {date}
        </Tooltip>
      }
    >
      <span>
        &nbsp;
        {datePart || ""} | {timePart || ""}
      </span>
    </OverlayTrigger>
  );
}

export function DateTimeFormat({ date, type = "created" }) {
  const formattedDate = getDateFormatByRegion(date);
  if (!formattedDate) return null;

  const [datePart, timePart] = formattedDate.split(" | ");

  return (
    <Tooltip title={formattedDate} arrow disableInteractive>
      <span style={{ cursor: "default", whiteSpace: "nowrap" }}>
        {datePart || ""} | {timePart || ""}
      </span>
    </Tooltip>
  );
}
